CREATE TABLE "Brand" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"website" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Product" ("id" TEXT NOT NULL PRIMARY KEY,"sku" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"origin" TEXT NOT NULL,"manufacturer" TEXT NOT NULL,"imageUrl" TEXT,"brandId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Product_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ProductUnit" ("id" TEXT NOT NULL PRIMARY KEY,"token" TEXT NOT NULL,"serialNumber" TEXT NOT NULL,"batchNumber" TEXT NOT NULL,"manufacturedAt" DATETIME NOT NULL,"expiresAt" DATETIME,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"riskFlag" BOOLEAN NOT NULL DEFAULT false,"scanThreshold" INTEGER NOT NULL DEFAULT 10,"productId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProductUnit_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TraceEvent" ("id" TEXT NOT NULL PRIMARY KEY,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"location" TEXT NOT NULL,"occurredAt" DATETIME NOT NULL,"unitId" TEXT NOT NULL,CONSTRAINT "TraceEvent_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "ProductUnit" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "VerificationLog" ("id" TEXT NOT NULL PRIMARY KEY,"tokenAttempt" TEXT NOT NULL,"verdict" TEXT NOT NULL,"ipAddress" TEXT,"userAgent" TEXT,"unitId" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "VerificationLog_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "ProductUnit" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "SuspiciousReport" ("id" TEXT NOT NULL PRIMARY KEY,"reason" TEXT NOT NULL,"details" TEXT,"contact" TEXT,"status" TEXT NOT NULL DEFAULT 'OPEN',"unitId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SuspiciousReport_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "ProductUnit" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Product_sku_key" ON "Product"("sku");
CREATE UNIQUE INDEX "ProductUnit_token_key" ON "ProductUnit"("token");
CREATE UNIQUE INDEX "ProductUnit_serialNumber_key" ON "ProductUnit"("serialNumber");
